function P.ArchiveUnsupportedPets()
  local s=P.state
  s.archivedPets=type(s.archivedPets)=="table" and s.archivedPets or {}
  s.archivedFinds=type(s.archivedFinds)=="table" and s.archivedFinds or {}
  local kept,finds={},{}
  for _,pet in ipairs(s.pets)do
    if P.IsAllowedSpecies(pet.species)then kept[#kept+1]=pet
    else
      -- The gear registry retains each item; clearing ownership returns it to
      -- the bag, preserving overflow when a previous save is already full.
      pet.gear={};pet.resting=false
      s.archivedPets[#s.archivedPets+1]=pet
      if s.active==pet.id then s.active=nil end
      if P.viewID==pet.id then P.viewID=nil end
    end
  end
  for _,entry in ipairs(s.finds)do
    if P.IsAllowedSpecies(entry.species)then finds[#finds+1]=entry
    else s.archivedFinds[#s.archivedFinds+1]=entry end
  end
  s.pets=kept;s.finds=finds
  if not s.active then
    for _,pet in ipairs(kept)do if not pet.deadAt then s.active=pet.id;break end end
  end
end
